/bin/bash -lc "python - <<'PY'
from pathlib import Path
import re
for f in sorted(Path('/docs').glob('*.txt')):
    page='?'
    hits=[]
    for line in f.read_text().splitlines():
        m=re.search(r'--- page (\\d+) ---',line)
        if m: page=m.group(1)
        if re.search(r'govern|florida',line,re.I): hits.append(f'p. {page}: {line}')
    print(f.name[:-4])
    print('\\n'.join(hits))
PY"

